message.content:
{
  "gate_token": "JZouYV8BuzMOUXy4oUwj-A",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hilltop at dusk, ink-stained coat flapping, a brass compass pinning a hand-drawn map open over cracked stones, with the broken silhouette of the city below.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "An oil lamp with a single glowing eye in its flame floats beside the map, casting a wary amber glow on Mara's tired face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox is wound up for scouting.",
      "visual_description": "A small clockwork fox with blue glass eyes stands on a mossy stone, its key-wind tail ticking as Mara turns the brass key with ink-smudged fingers.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the looming castle gates.",
      "visual_description": "Massive iron-banded gates hang crooked under faded royal banners; the tin fox sniffs the threshold while Mara crouches in shadow.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver emerges from a tall mirror.",
      "visual_description": "A figure in a clear diving helmet steps from a cracked floor-length mirror inside the gatehouse, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The cursed tower beckons with a false light.",
      "visual_description": "A leaning tower glows green at its peak; the oracle lamp's eye narrows in distrust as Mara shakes her head, pulling her companions away.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a winged beast rattle loose tiles overhead.",
      "visual_description": "A vast scaled shadow sweeps across cracked rooftops; the tin fox flattens its ears as the four companions duck behind a toppled fountain.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Pale eyes glint through gaps in nailed planks along a narrow alley; Mara presses a reassuring hand to a shutter while the lamp dims politely.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "They discover the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A plump official snores against a ledger pillow, stamped papers stuck to his sleeves, a tipped inkwell pooling near his boots.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox lifts a brass key from the sleeper's belt.",
      "visual_description": "The clockwork fox delicately hooks a ring of keys with its muzzle, blue glass eyes wide, while the tax collector mumbles into his ledger.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol marches past in lockstep.",
      "visual_description": "Steel boots tramp through a moonlit square; Mara and the glass diver press flat against a banner-draped wall, the lamp pinched shut to hide its glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "guard_check": null,
      "visual_description": "A heavy door etched with shifting runes pulses faintly; the oracle lamp whispers the correct sequence as Mara traces glowing symbols.",
      "caption": "A magic door demands the right words.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver slips through a stained-glass window.",
      "visual_description": "Coat rippling with colored light, the diver wades headfirst into a tall chapel window as if it were water, leaving a single concentric ripple.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Inside, the captive is found in a mirrored cell.",
      "visual_description": "The glass diver kneels beside a chained figure surrounded by warped mirrors; a reflection of Mara waves encouragement from the silvered glass.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox chews through enchanted chains.",
      "visual_description": "Sparks fly from the clockwork fox's tiny teeth as glowing links snap one by one; the oracle lamp hovers close for light.",
      "characters": ["tin_fox", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "They flee past the cursed tower as alarms ring.",
      "visual_description": "Bells clang from crooked spires; royal banners flap loose as the companions sprint down a rubble-strewn boulevard, the lamp streaming a comet trail.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The narrow bridge stretches over a black ravine.",
      "visual_description": "A crumbling stone bridge arches into mist; Mara checks her compass at the threshold while the glass diver scouts a missing plank ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They cross to safety as dawn breaks behind them.",
      "visual_description": "Silhouettes on the far end of the bridge against a pink-gold sky; the ruined city smolders behind, the tin fox's tail still ticking softly.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

